			cas: program(gl, VERT_POST, FSQ.LOOK_CAS_SHADER, ["u_img", "u_px", "u_sharp"]),
			color: program(gl, VERT_POST, FSQ.LOOK_COLOR_SHADER, ["u_img", "u_a", "u_b", "u_c", "u_n"]),
